import type { Token, TokenModel } from '@lumen/design-sources';
import type { OutputFile, Target } from '../core/target.js';
import { cssLayers, type Declarations } from './cssLayers.js';
import {
  breakpointMinWidths,
  coreFiles,
  orderedBreakpoints,
} from './selections.js';
import { motion, shadowUtilities, typographyUtilities } from './tailwind.js';

const HEADER = `/*
 * Do not edit directly, this file was auto-generated by design-build.
 */`;

const FALLBACK_COLORS: Declarations = {
  transparent: 'transparent',
  inherit: 'inherit',
  current: 'currentColor',
};

const block = (
  selector: string,
  declarations: Declarations,
  indent = '',
): string =>
  `${indent}${selector} {\n${Object.entries(declarations)
    .map(([property, value]) => `${indent}  ${property}: ${value};`)
    .join('\n')}\n${indent}}`;

/** `--background-canvas-muted` → `canvas-muted` for the variables with a prefix. */
const keysWithPrefix = (
  variables: Declarations,
  prefix: string,
  exclude?: string,
): string[] =>
  Object.keys(variables)
    .filter((name) => name.startsWith(prefix))
    .filter((name) => !exclude || !name.startsWith(exclude))
    .map((name) => name.slice(prefix.length).toLowerCase());

/** A Tailwind theme namespace reset, then mapped onto Lumen variables. */
const namespace = (prefix: string, values: Declarations): Declarations => ({
  [`${prefix}-*`]: 'initial',
  ...Object.fromEntries(
    Object.entries(values).map(([key, value]) => [`${prefix}-${key}`, value]),
  ),
});

const mapTo = (keys: string[], variablePrefix: string): Declarations =>
  Object.fromEntries(keys.map((key) => [key, `var(${variablePrefix}${key})`]));

/**
 * The Tailwind v4 theme: a shared `theme.css` (namespaces, primitives,
 * typography, utilities) and one small entry per brand, plus `all-brands.css`
 * where brands switch by class, as the presets did. Wiring with no design
 * value lives in the hand-written `lumen.css`.
 */
export const tailwindV4Target = (outDir: string): Target<TokenModel> => ({
  name: 'tailwind-v4',
  outDir,
  owns: (file) => file !== 'lumen.css' && file.endsWith('.css'),
  // Prettier would rewrite values (`0.10` → `0.1`) the preset keeps as written.
  format: false,
  emit: (model) => {
    const breakpoints = orderedBreakpoints(model);
    const layers = cssLayers(model, breakpoints);
    const core = coreFiles(model);
    const coreTokens = model.tokens(core);
    const resolveCore = (token: Token): unknown => model.resolve(token, core);

    const screens = Object.fromEntries(
      [...breakpointMinWidths(model)].map(([name, width]) => [
        name,
        `${width}px`,
      ]),
    );
    const { durations, easings } = motion(coreTokens, resolveCore);
    const duration = (key: string): string => {
      if (!durations[key]) {
        throw new Error(
          `An animation needs duration.${key}, which is gone from the sources`,
        );
      }
      return durations[key];
    };

    const { primitives } = layers;
    // Every brand × theme has the same keys (validation enforces it), so the
    // namespaces are shared.
    const semantic = layers.themes[0].declarations;
    const background = keysWithPrefix(semantic, '--background-');
    const text = keysWithPrefix(semantic, '--text-');
    const border = keysWithPrefix(semantic, '--border-', '--border-width');
    const crypto = keysWithPrefix(semantic, '--color-crypto-');
    const discover = keysWithPrefix(semantic, '--color-discover-');

    const backgroundLike = {
      ...mapTo(background, '--background-'),
      ...FALLBACK_COLORS,
      ...Object.fromEntries(
        crypto.map((key) => [`crypto-${key}`, `var(--color-crypto-${key})`]),
      ),
      ...Object.fromEntries(
        discover.map((key) => [
          `discover-${key}`,
          `var(--color-discover-${key})`,
        ]),
      ),
    };
    const textLike = { ...mapTo(text, '--text-'), ...FALLBACK_COLORS };
    const borderLike = { ...mapTo(border, '--border-'), ...FALLBACK_COLORS };

    const sizes = keysWithPrefix(primitives, '--size-');
    const spacing = keysWithPrefix(primitives, '--spacing-');
    const spacingKeys = new Set(spacing);
    // The preset resolved `max-w-*` and `basis-*` from spacing first, then
    // sizes: only the size steps spacing lacks get their own entry.
    const sizeOnly = sizes.filter((key) => !spacingKeys.has(key));

    const animations: Declarations = {
      'content-show': `content-show ${duration('300')} ease-in`,
      'content-hide': `content-hide ${duration('300')} ease-out`,
      'fade-in': `fade-in ${duration('300')} ease-in`,
      'fade-out': `fade-out ${duration('300')} ease-out`,
      ...Object.fromEntries(
        ['top', 'bottom', 'left', 'right'].flatMap((side) => [
          [
            `slide-in-from-${side}`,
            `slide-in-from-${side} ${duration('200')} ease-in`,
          ],
          [
            `slide-out-to-${side}`,
            `slide-out-to-${side} ${duration('200')} ease-out`,
          ],
        ]),
      ),
      'translate-from-right': `translate-from-right ${duration('250')} ${easings['ease-in-out']}`,
    };

    const themeNamespaces: Declarations = {
      '--color-*': 'initial',
      '--spacing': 'initial',
      ...namespace('--spacing', mapTo(spacing, '--spacing-')),
      ...namespace(
        '--radius',
        mapTo(
          keysWithPrefix(primitives, '--border-radius-'),
          '--border-radius-',
        ),
      ),
      ...namespace(
        '--backdrop-blur',
        mapTo(
          keysWithPrefix(primitives, '--backdrop-blur-'),
          '--backdrop-blur-',
        ),
      ),
      ...Object.assign(
        {},
        ...[
          '--width',
          '--height',
          '--size',
          '--min-width',
          '--min-height',
          '--max-height',
          '--columns',
        ].map((ns) => namespace(ns, mapTo(sizes, '--size-'))),
      ),
      ...namespace('--max-width', mapTo(sizeOnly, '--size-')),
      ...namespace('--flex-basis', mapTo(sizeOnly, '--size-')),
      ...Object.fromEntries(
        Object.entries(animations).map(([key, value]) => [
          `--animate-${key}`,
          value,
        ]),
      ),
      '--text-*': 'initial',
      '--font-weight-*': 'initial',
      '--leading-*': 'initial',
      // No `--box-shadow-color`: the preset's shadow colors never reached
      // Tailwind v4, so `shadow-<color>` classes don't exist today.
      '--shadow-*': 'initial',
      ...namespace('--background-color', backgroundLike),
      ...namespace('--accent-color', backgroundLike),
      ...namespace('--fill', backgroundLike),
      ...namespace('--text-color', textLike),
      ...namespace('--caret-color', textLike),
      ...namespace('--placeholder-color', textLike),
      ...namespace('--border-color', borderLike),
      ...namespace('--stroke', borderLike),
      ...namespace('--ring-color', borderLike),
      ...namespace('--outline-color', borderLike),
      ...namespace('--ring-offset-color', borderLike),
      ...namespace('--text-decoration-color', borderLike),
    };

    const typography = typographyUtilities(
      model
        .tokens(
          model.select(['primitives', 'breakpoint'], {
            breakpoint: breakpoints[0],
          }),
        )
        .filter(({ source }) => source.collection === 'breakpoint'),
    );
    const iconStep = (
      prefix: string,
      utility: (step: string) => string,
    ): string[] => keysWithPrefix(primitives, prefix).map(utility);
    const utilities = [
      ...Object.entries({
        ...typography,
        ...shadowUtilities(coreTokens, resolveCore),
      }).map(([selector, declarations]) =>
        block(`@utility ${selector.slice(1)}`, declarations),
      ),
      ...iconStep('--icon-width-', (step) =>
        block(`@utility icon-w-${step}`, {
          width: `var(--icon-width-${step})`,
        }),
      ),
      ...iconStep('--icon-height-', (step) =>
        block(`@utility icon-h-${step}`, {
          height: `var(--icon-height-${step})`,
        }),
      ),
      ...iconStep('--icon-border-width-', (step) =>
        block(`@utility icon-stroke-${step}`, {
          'stroke-width': `calc(var(--icon-border-width-${step}) / ${Number(step) / 16})`,
        }),
      ),
      ...iconStep('--spot-width-', (step) =>
        block(`@utility spot-w-${step}`, {
          width: `var(--spot-width-${step})`,
        }),
      ),
      ...iconStep('--spot-height-', (step) =>
        block(`@utility spot-h-${step}`, {
          height: `var(--spot-height-${step})`,
        }),
      ),
      ...crypto
        .filter((key) => !key.endsWith('-0'))
        .sort()
        .map((key) =>
          block(`@utility bg-gradient-${key}`, {
            'background-image': `linear-gradient(161deg, var(--color-crypto-${key}) 0%, var(--color-crypto-${key}-0) 100%)`,
          }),
        ),
    ];

    const typographyLayers = layers.breakpoints.map(
      ({ breakpoint, declarations }, index) =>
        index === 0
          ? block(':root', declarations, '  ')
          : `  @media (min-width: ${screens[breakpoint]}) {\n${block(':root', declarations, '    ')}\n  }`,
    );

    const themeFile: OutputFile = {
      path: 'theme.css',
      contents: [
        `${HEADER}\n\n/* Shared by every brand entry: import a brand file, not this one. */`,
        `@import './lumen.css';`,
        block('@theme inline reference', themeNamespaces),
        block('@theme', {
          '--breakpoint-*': 'initial',
          ...Object.fromEntries(
            Object.entries(screens).map(([key, value]) => [
              `--breakpoint-${key}`,
              value,
            ]),
          ),
        }),
        `@layer base {\n${[block(':root', primitives, '  '), ...typographyLayers].join('\n')}\n}`,
        ...utilities,
        '',
      ].join('\n\n'),
    };

    const entry = (
      name: string,
      description: string,
      selectors: { selector: string; brand: string; theme: string }[],
    ): OutputFile => ({
      path: `${name}.css`,
      contents: [
        `${HEADER}\n\n/* ${description} */`,
        `@import './theme.css';`,
        `@layer base {\n${selectors
          .map(({ selector, brand, theme }) => {
            const layer = layers.themes.find(
              (candidate) =>
                candidate.brand === brand && candidate.theme === theme,
            );
            return block(selector, layer?.declarations ?? {}, '  ');
          })
          .join('\n')}\n}`,
        '',
      ].join('\n\n'),
    });

    const brands = model.modesOf('brand');
    return [
      themeFile,
      ...brands.map((brand) =>
        entry(brand, `The ${brand} brand: light on :root, dark under .dark.`, [
          { selector: ':root', brand, theme: 'light' },
          { selector: '.dark', brand, theme: 'dark' },
        ]),
      ),
      entry(
        'all-brands',
        'Every brand, switched by a class on a parent (.enterprise, .ledger-live, .websites), dark under .dark.',
        brands.flatMap((brand) => [
          { selector: `.${brand}`, brand, theme: 'light' },
          { selector: `.${brand}.dark`, brand, theme: 'dark' },
        ]),
      ),
    ];
  },
});
